import{_ as t,o as a,c as o,a1 as i}from"./chunks/framework.C5u0ZYB0.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md","lastUpdated":1789948117000}'),s={name:"docs/index.md"};function r(n,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Aquilifer is a browser extension that acts as a secure LLM provider for websites, the same idea as a crypto wallet extension like MetaMask, but for LLM access instead of a blockchain account.</p><p>A website never sees your API key. It asks the extension for a completion; the extension holds the credential, enforces your permissions and rate limits, and hands back only the response.</p><h2 id="the-three-things-that-never-change" tabindex="-1">The three things that never change <a class="header-anchor" href="#the-three-things-that-never-change" aria-label="Permalink to &quot;The three things that never change&quot;">​</a></h2><p>However this project grows, these stay true: they&#39;re the entire point of it, not implementation details that might get relaxed later:</p><ul><li><strong>The website can never obtain your credentials.</strong> It gets a completion, never a key.</li><li><strong>The website can never choose which provider answers.</strong> You bind a provider to a site when you connect it; the site only ever sends prompts and receives completions.</li><li><strong>Your own usage limits always apply</strong>, regardless of why a site is calling, including if it&#39;s only using Aquilifer as a fallback for its own, separate integration.</li></ul><h2 id="what-s-on-this-page-vs-the-rest-of-the-docs" tabindex="-1">What&#39;s on this page vs. the rest of the docs <a class="header-anchor" href="#what-s-on-this-page-vs-the-rest-of-the-docs" aria-label="Permalink to &quot;What&#39;s on this page vs. the rest of the docs&quot;">​</a></h2><ul><li><strong><a href="/projects/aquilifer/docs/installing">Installing</a></strong>: how to get it running today (it isn&#39;t on the Chrome Web Store yet).</li><li><strong><a href="/projects/aquilifer/docs/connecting">Connecting a site</a></strong>: the approval flow, and what &quot;connect once, then silent&quot; actually means.</li><li><strong><a href="/projects/aquilifer/docs/providers">Providers</a></strong>: Anthropic, OpenAI, and self-hosted/local models.</li><li><strong><a href="/projects/aquilifer/docs/popup">The toolbar popup</a></strong>: the quick-glance view: what&#39;s connected, live rate-limit standing, switching models and the default provider.</li><li><strong><a href="/projects/aquilifer/docs/rate-limiting">Rate limiting</a></strong> and <strong><a href="/projects/aquilifer/docs/history">History</a></strong>: the controls and the audit log that back the trust model.</li><li><strong><a href="/projects/aquilifer/docs/vault">The vault</a></strong>: optional password-based encryption for stored API keys, and importantly, what it does <em>not</em> protect.</li><li><strong><a href="/projects/aquilifer/docs/appearance">Appearance</a></strong>: font size and the toolbar popup&#39;s width.</li><li><strong><a href="/projects/aquilifer/docs/api">The page-facing API</a></strong>: for developers integrating Aquilifer into a website.</li><li><strong><a href="/projects/aquilifer/docs/limitations">Limitations &amp; downsides</a></strong>: read this one. Every project has tradeoffs; this page is where they&#39;re written down instead of left for you to discover.</li><li><strong><a href="/projects/aquilifer/docs/privacy">Privacy policy</a></strong>: what&#39;s stored, what&#39;s sent over the network and to whom, and that there&#39;s no analytics or tracking anywhere in the extension.</li></ul>',8)])])}const f=t(s,[["render",r]]);export{g as __pageData,f as default};
